# We generate a nontrivial instance by selecting rows, cols in [4..7],
# then computing the full (k_black, t_gray) distribution via a transfer-matrix DP.
# We then pick a pair with substantial count to ensure difficulty.

def build_states(c):
    states = []  # list of tuples of length c with entries 0(W),1(G),2(B)
    bcnt = []
    gcnt = []
    # Enumerate all 3^c states by base-3 integer representation
    for x in range(3**c):
        s = []
        y = x
        for _ in range(c):
            s.append(y % 3)
            y //= 3
        # s holds digits for columns 0..c-1
        ok = True
        for j in range(c-1):
            a = s[j]
            b = s[j+1]
            # Horizontal constraints within a row:
            # - black (2) cannot be adjacent to black (2)
            # - black (2) cannot be adjacent to gray (1)
            # - gray (1) cannot be adjacent to black (2)
            if (a == 2 and (b == 2 or b == 1)) or (a == 1 and b == 2):
                ok = False
                break
        if not ok:
            continue
        states.append(tuple(s))
        bcnt.append(sum(1 for v in s if v == 2))
        gcnt.append(sum(1 for v in s if v == 1))
    return states, bcnt, gcnt

def build_compat(states, c):
    # prev -> list of curr indices that are compatible across rows
    n = len(states)
    compat = [[] for _ in range(n)]
    for i, prev in enumerate(states):
        for j, curr in enumerate(states):
            ok = True
            # Orth adjacency constraints between rows:
            for k in range(c):
                if prev[k] == 2:
                    # black above prohibits black or gray below; only white allowed
                    if curr[k] != 0:
                        ok = False
                        break
                elif prev[k] == 1:
                    # gray above prohibits black below
                    if curr[k] == 2:
                        ok = False
                        break
            if not ok:
                continue
            # Diagonal gray-gray constraint:
            for k in range(c-1):
                if (prev[k] == 1 and curr[k+1] == 1) or (prev[k+1] == 1 and curr[k] == 1):
                    ok = False
                    break
            if ok:
                compat[i].append(j)
    return compat

def full_distribution(r, c):
    states, bcnt, gcnt = build_states(c)
    if not states:
        return {}, states, bcnt, gcnt
    compat = build_compat(states, c)
    # DP over rows tracking (state_index, total_black, total_gray)
    dp = {}
    for i in range(len(states)):
        key = (i, bcnt[i], gcnt[i])
        dp[key] = dp.get(key, 0) + 1
    for _ in range(1, r):
        next_dp = {}
        for (prev_i, kb, tg), cnt in dp.items():
            for curr_i in compat[prev_i]:
                nkb = kb + bcnt[curr_i]
                ntg = tg + gcnt[curr_i]
                key = (curr_i, nkb, ntg)
                next_dp[key] = next_dp.get(key, 0) + cnt
        dp = next_dp
        if not dp:
            break
    # Aggregate over final states
    dist = {}
    for (i, kb, tg), cnt in dp.items():
        dist[(kb, tg)] = dist.get((kb, tg), 0) + cnt
    return dist, states, bcnt, gcnt

# Try multiple times to find a hard instance
for _attempt in range(60):
    rows = rng.randint(4, 7)
    cols = rng.randint(4, 7)
    dist, states, bcnt, gcnt = full_distribution(rows, cols)
    # Select candidate pairs with substantial counts to avoid trivial instances
    candidates = [(kb, tg, cnt) for (kb, tg), cnt in dist.items() if cnt >= 150 and cnt <= 500000 and kb > 0 and tg > 0]
    if not candidates:
        continue
    kb, tg, _ = rng.choice(candidates)
    return {'rows': rows, 'cols': cols, 'k_black': kb, 't_gray': tg}

# Fallback: deterministic hard-ish instance
rows, cols = 5, 5
dist, states, bcnt, gcnt = full_distribution(rows, cols)
if dist:
    # Choose a pair with largest count but not trivial zeros
    sorted_pairs = sorted([(cnt, kb, tg) for (kb, tg), cnt in dist.items() if kb > 0 and tg > 0], reverse=True)
    if sorted_pairs:
        cnt, kb, tg = sorted_pairs[0]
        return {'rows': rows, 'cols': cols, 'k_black': kb, 't_gray': tg}
# Last resort: minimal nontrivial parameters
return {'rows': 4, 'cols': 4, 'k_black': 3, 't_gray': 4}

